import React, { useState, useEffect } from "react";
import "./App.css";
import Navbar from "./components/Navbar";
import SecondaryNavbar from "./components/SecondaryNavbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test";

const App = () => {
  const [activePage, setActivePage] = useState("chat");
  const [messages, setMessages] = useState([]);
  const [latestQuery, setLatestQuery] = useState("");
  const [topics, setTopics] = useState([]);

  // Load messages & topics from localStorage on app start
  useEffect(() => {
    const savedMessages = JSON.parse(localStorage.getItem("messages")) || [];
    const savedTopics = JSON.parse(localStorage.getItem("topics")) || [];
    setMessages(savedMessages);
    setTopics(savedTopics);
  }, []);

  // Save messages & topics to localStorage when updated
  useEffect(() => {
    localStorage.setItem("messages", JSON.stringify(messages));
  }, [messages]);

  useEffect(() => {
    localStorage.setItem("topics", JSON.stringify(topics));
  }, [topics]);

  return (
    <div className="app-container">
      {/* Top Secondary Navbar */}
      <SecondaryNavbar setActivePage={setActivePage} />  {/* ✅ Fix applied */}

      {/* Sidebar Navbar */}
      <Navbar activePage={activePage} setActivePage={setActivePage} />

      {/* Main Content */}
      <div className="content">
        {activePage === "chat" && (
          <ChatBox 
            messages={messages} 
            setMessages={setMessages} 
            setLatestQuery={setLatestQuery} 
          />
        )}
        {activePage === "youtube" && <YouTube latestQuery={latestQuery} />}
        {activePage === "wikipedia" && <Wikipedia latestQuery={latestQuery} />}
        {activePage === "test" && (
          <Test 
            messages={messages} 
            latestQuery={latestQuery} 
            topics={topics} 
            setTopics={setTopics} 
          />
        )}
      </div>

      {/* Footer */}
      <footer className="footer">
        <p>&copy; 2025 PAT | @Indrajit002</p>
      </footer>
    </div>
  );
};

export default App;
